import numpy as np
g=np.array(grid)
H,W=g.shape
iso={2:0,5:0}
posiso={2:[],5:[]}
for r in range(H):
    for c in range(W):
        v=g[r,c]
        nb=[]
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
            rr,cc=r+dr,c+dc
            if 0<=rr<H and 0<=cc<W: nb.append(g[rr,cc])
        if all(x!=v for x in nb):
            iso[v]+=1; posiso[v].append((r,c))
print(iso)
print(posiso)

try:
    import refine
    await refine.run()
    print("refinement queued")
except Exception as e:
    print("refine unavailable:", e)
